package com.primehr.learningdevelopment.delivery.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity@Table(name="ld_program_source",uniqueConstraints=@UniqueConstraint(name="uk_ld_program_source",columnNames={"agency_id","program_id","plan_source_id"}))
public class LdProgramSource extends RspAuditedEntity{@Column(name="program_id",nullable=false,length=36)private String programId;@Column(name="plan_source_id",nullable=false,length=36)private String planSourceId;@Column(name="source_fingerprint",nullable=false,length=64)private String sourceFingerprint;@Column(name="development_objective",nullable=false,length=3000)private String developmentObjective;@Column(name="success_measure",nullable=false,length=2000)private String successMeasure;@Column(name="display_order",nullable=false)private int displayOrder;protected LdProgramSource(){}public LdProgramSource(String agency,String program,String source,String fingerprint,String objective,String measure,int order){super(agency);programId=requiredText(program,"programId");planSourceId=requiredText(source,"planSourceId");sourceFingerprint=requiredText(fingerprint,"sourceFingerprint");developmentObjective=requiredText(objective,"developmentObjective");successMeasure=requiredText(measure,"successMeasure");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getProgramId(){return programId;}public String getPlanSourceId(){return planSourceId;}public String getSourceFingerprint(){return sourceFingerprint;}public String getDevelopmentObjective(){return developmentObjective;}public String getSuccessMeasure(){return successMeasure;}public int getDisplayOrder(){return displayOrder;}}
